"""
Generate philosophy debate generic actions for the Academy of Sciences panel.
"""

import sys
import argparse
from pathlib import Path

if hasattr(sys.stdout, "reconfigure"):
    sys.stdout.reconfigure(encoding="utf-8", errors="replace")

import yaml

REPO_ROOT = Path(__file__).resolve().parents[4]
DATA_FILE = REPO_ROOT / "data" / "philosophy_debate_actions.yaml"
OUT_FILE = REPO_ROOT / "src" / "in_game" / "common" / "generic_actions" / "tv_philosophy_actions.txt"

HEADER = """\
# @Generated by scripts/in_game/common/generic_actions/gen_tv_philosophy_actions.py
#   Data:    data/philosophy_debate_actions.yaml
#   Regen:   conda run --no-capture-output -n eu5 python scripts/in_game/common/generic_actions/gen_tv_philosophy_actions.py
# Do not edit directly - modify the data file and re-run the generator.
"""


def _potential_block() -> str:
    return """\
\tpotential = {
\t\tcustom_tooltip = {
\t\t\ttext = TV_HAS_ACADEMY_IO_MEMBER_TT
\t\t\tscope:actor = { has_variable = tv_academy_io_member }
\t\t}
\t}"""


def gen_select_action(slot: int, action: int) -> str:
    return f"""\
tv_philosophy_select_slot_{slot}_action_{action} = {{
\ttype = owncountry
\tsound = UI_action_religion_generic
\tshow_message = no
\tai_tick = never
\tautomation_tick = never
{_potential_block()}
\tallow = {{
\t\tscope:actor = {{
\t\t\tvar:tv_academy_philosophy_phase ?= 1
\t\t\tNOT = {{ has_variable = tv_academy_philosophy_round_pending }}
\t\t\tvar:tv_academy_philosophy_slot_{slot}_allow ?= 1
\t\t\tvar:tv_academy_philosophy_slot_{slot}_action ?= {action}
\t\t}}
\t}}
\teffect = {{
\t\tscope:actor = {{
\t\t\ttv_academy_philosophy_select_action_effect = {{ slot = {slot} action = {action} }}
\t\t}}
\t}}
\tai_will_do = {{ add = -100 }}
}}
"""


def gen_execute_action() -> str:
    return f"""\
tv_philosophy_execute_selected_action = {{
\ttype = owncountry
\tsound = UI_action_religion_generic
\tshow_message = yes
\tai_tick = never
\tautomation_tick = never
{_potential_block()}
\tallow = {{
\t\tscope:actor = {{
\t\t\ttv_academy_philosophy_can_execute_selected_action_trigger = yes
\t\t}}
\t}}
\teffect = {{
\t\tscope:actor = {{
\t\t\ttv_academy_philosophy_execute_selected_action_effect = yes
\t\t}}
\t}}
\tai_will_do = {{ add = -100 }}
}}
"""


def generate(data: dict) -> str:
    action_ids = [int(action["id"]) for action in data["actions"]]
    if action_ids != [1, 2, 3, 4, 5, 6]:
        raise ValueError("Philosophy debate actions must be ids 1..6 in order")

    parts = [HEADER]
    for slot in range(1, 4):
        for action in action_ids:
            parts.append(gen_select_action(slot, action))
    parts.append(gen_execute_action())
    return "\n".join(parts)


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--dry", action="store_true", help="Print to stdout instead of writing")
    args = parser.parse_args()

    with DATA_FILE.open(encoding="utf-8") as file:
        data = yaml.safe_load(file)

    content = generate(data)
    if args.dry:
        print(content)
    else:
        OUT_FILE.write_text(content, encoding="utf-8-sig")
        print(f"Written: {OUT_FILE.relative_to(REPO_ROOT)}")


if __name__ == "__main__":
    main()
